name: PR Issue Link Check
on:
  pull_request:
    types: [opened, edited, synchronize, reopened]

jobs:
  check-pr-description:
    runs-on: ubuntu-latest
    steps:
      - name: Check PR Description for Issue Link
        id: check_pr
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const pr = context.payload.pull_request;
            const prTitle = pr.title;
            const prBody = pr.body || '';

            // Pattern to match issue references in PR title or body
            const issuePattern = /(?:fixes|closes|resolves)\s+#(\d+)/gi;

            // Extract all issue numbers from title and body
            const titleMatches = prTitle.match(issuePattern);
            const bodyMatches = prBody.match(issuePattern);

            let allMatches = [];
            if (titleMatches) {
              allMatches = allMatches.concat(titleMatches);
            }
            if (bodyMatches) {
              allMatches = allMatches.concat(bodyMatches);
            }

            // If no issue references found, fail the check
            if (!allMatches || allMatches.length === 0) {
              core.setFailed('Pull Request must reference an issue. Please use "Fixes #123", "Closes #456", or "Resolves #789" format.');
              return;
            }

            // Extract issue numbers
            const issueNumbers = [];
            const regex = /(?:fixes|closes|resolves)\s+#(\d+)/gi;
            let match;
            while ((match = regex.exec(allMatches.join(' '))) !== null) {
              issueNumbers.push(match[1]);
            }

            // Remove duplicates
            const uniqueIssueNumbers = [...new Set(issueNumbers)];

            // Validate each issue exists
            const issuesExist = await Promise.all(uniqueIssueNumbers.map(async (issueNumber) => {
              try {
                const response = await github.rest.issues.get({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: parseInt(issueNumber)
                });
                return true;
              } catch (error) {
                if (error.status === 404) {
                  return false;
                }
                throw error;
              }
            }));

            // If any issue doesn't exist, fail the check
            if (issuesExist.includes(false)) {
              const missingIssues = uniqueIssueNumbers.filter((_, index) => !issuesExist[index]);
              core.setFailed(`The following referenced issues do not exist: ${missingIssues.join(', ')}. Please ensure all referenced issues exist.`);
              return;
            }

            // If we get here, all checks passed
            console.log(`All referenced issues (${uniqueIssueNumbers.join(', ')}) exist and are valid.`);
